with groups as(select c.id,c.level,row_number() over(partition by c.level,c.id order by s.name,s.id) k,s.id subject_id from schoolpro_classes c join schoolpro_subject_assignments sa on sa.class_id=c.id and sa.school_id=c.school_id join schoolpro_subjects s on s.id=sa.subject_id where c.school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and c.id in(select md5('ihlink-academy-test-v1:class:'||n)::uuid from generate_series(1,28)n) and sa.session='2025/2026') update schoolpro_subject_assignments sa set teacher_member_id=md5('ihlink-academy-test-v1:member:'||(case g.level::text when 'nursery' then 46 when 'primary' then 56 when 'junior_secondary' then 66 else 76 end+g.k)::text)::uuid from groups g where sa.class_id=g.id and sa.subject_id=g.subject_id and sa.session='2025/2026';
update schoolpro_subject_assignments sa set teacher_member_id=md5('ihlink-academy-test-v1:member:74')::uuid from schoolpro_subjects s join schoolpro_classes c on c.school_id=s.school_id where sa.subject_id=s.id and sa.class_id=c.id and sa.school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and c.level::text in('junior_secondary','senior_secondary') and s.name='Mathematics' and sa.session='2025/2026';
